'use client'

import { useEffect, useState } from 'react'
import {
  COOKIE_CONSENT_EVENT,
  getCookieConsent,
  openCookieSettings
} from './cookieConsentUtils'

// Avoids the fragile `pb` URLs generated by Google's share dialog.
const MAP_URL =
  'https://www.google.com/maps?q=Fans+Coffee+%26+Bakery%2C+C.+del+Dr.+Esquerdo+180%2C+28007+Madrid&output=embed'

type ConsentAwareMapProps = {
  height?: number
  className?: string
}

export default function ConsentAwareMap({
  height = 250,
  className = ''
}: ConsentAwareMapProps) {
  const [isAllowed, setIsAllowed] = useState(false)

  useEffect(() => {
    const updatePermission = () => {
      setIsAllowed(getCookieConsent() === 'accepted')
    }

    updatePermission()
    window.addEventListener(COOKIE_CONSENT_EVENT, updatePermission)

    return () =>
      window.removeEventListener(COOKIE_CONSENT_EVENT, updatePermission)
  }, [])

  if (!isAllowed) {
    return (
      <div
        className={`flex flex-col items-center justify-center gap-3 bg-brand-cream px-5 text-center text-sm text-brand-burgundy/80 ${className}`}
        style={{ minHeight: height }}
        role='region'
        aria-label='Mapa de ubicación bloqueado hasta aceptar cookies'
      >
        <p>
          El mapa de Google está desactivado hasta que aceptes las cookies no
          necesarias.
        </p>
        <button
          type='button'
          className='brand-button brand-button--outline text-xs'
          onClick={openCookieSettings}
        >
          Configurar cookies
        </button>
      </div>
    )
  }

  return (
    <iframe
      title='Ubicación de Fans Coffee Bakery en Google Maps'
      src={MAP_URL}
      width='100%'
      height={height}
      loading='lazy'
      referrerPolicy='no-referrer'
      className={`block w-full max-w-full rounded-brand border-0 ${className}`}
    />
  )
}
